public class JWKeyParsing {
    public static void main(String[] args) {
        JWKeyParsing obj = new JWKeyParsing();
        obj.addBCProvider();
        KeyPair ed25519Keypair = obj.generateEd25519Keypair();

        try {
            X509Certificate x509Certificate = obj.generateSelfSignedCertificate(ed25519Keypair, "Ed25519", Security.getProvider("BC"));
            String pemCert = obj.toPem(x509Certificate);

//            JWK jwk = JWK.parseFromPEMEncodedX509Cert(pemCert);

            X509Certificate cert = obj.parseCert(pemCert);
            JWK okpJWK = obj.buildOctetKeyPairJWK(cert);
            System.out.println(okpJWK.toJSONString());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private void addBCProvider() {
        Security.addProvider(new BouncyCastleProvider());
    }

    private KeyPair generateEd25519Keypair() {
        try {
            KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("Ed25519");
            KeyPair keyPair = keyPairGenerator.generateKeyPair();
            System.out.println("Ed25519 keypair generated.");
            return keyPair;
        } catch (Exception e) {
            System.err.println("Ed25519 Keypair generation failed. \n Reason: " + e);
            throw new RuntimeException(e);
        }
    }

    private X509Certificate generateSelfSignedCertificate(KeyPair keyPair, String signAlgorithm, Provider provider) throws Exception {
        KeyUsage keyUsage = new KeyUsage(KeyUsage.digitalSignature | KeyUsage.keyCertSign);
        BasicConstraints basicConstraints = new BasicConstraints(2);
        long now = System.currentTimeMillis();
        Date notBefore = new Date(now);
        Date notAfter = new Date(now + 365 * 24 * 60 * 60 * 1000L); // Valid for 1 year
        X500Name distName = new X500Name("C=IN, ST=Karnataka, O=CyberPWN OU=Product Team, CN=Testing");
        BigInteger serialNumber = new BigInteger(Long.toString(now));
        ContentSigner contentSigner = new JcaContentSignerBuilder(signAlgorithm).setProvider(provider).build(keyPair.getPrivate());
        X509v3CertificateBuilder certBuilder = new JcaX509v3CertificateBuilder(distName, serialNumber, notBefore,
                notAfter, distName, keyPair.getPublic());
        JcaX509ExtensionUtils extensionUtils = new JcaX509ExtensionUtils();
